#include <bits/stdc++.h>
using namespace std;
#define int long long

const int MOD = 998244353;

signed main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--) {
        int n;
        cin>>n;
        vector<int> a(n + 1);
        vector<vector<int>> pos(n + 1);
        
        for(int i = 1; i<=n; i++) {
            cin>>a[i];
            pos[a[i]].push_back(i);
        }
        vector<int> dp(n + 1, 0);
        dp[0] = 1;
        for(int v = 1; v<=n; v++) {
            vector<int> ndp(n + 1, 0);
            for(int l = 0; l<v; l++) {
                if(dp[l] == 0) continue;
                int r = v - 1 - l;
                int L = l + 1;
                int R = n - r;
                int sides = (v == n ? 1 : 2);
                for(int side = 0; side < sides; side++) {
                    int newL;
                    int p;
                    if(side == 0) {
                        p = L;
                        newL = l + 1;
                    }
                    else {
                        p = R;
                        newL = l;
                    }
                    bool ok = true;
                    for(int i : pos[v]) {
                        bool prefix = false;
                        if(i >= p) {
                            int smaller = l + max(0LL, i - R);
                            if(smaller == (i - 1)/2) prefix = true;
                        }
                        bool suffix = false;
                        if(i <= p) {
                            int smaller = r + max(0LL, L - i);
                            if(smaller == (n - i) / 2) suffix = true;
                        }
                        if(!prefix && !suffix) {
                            ok = false;
                            break;
                        }
                    }
                    if(ok) {
                        ndp[newL] += dp[l];
                        if(ndp[newL] >= MOD) ndp[newL] -= MOD;
                    } 
                }
            }
            dp.swap(ndp);
        }
        int ans = 0;
        for(int l = 0; l<=n; l++) {
            ans += dp[l];
            if(ans >= MOD) ans -= MOD;
        }
        cout<<ans<<"\n";
    }
}
